            reward: { zh: '⚖️ 264 歲！安安把兩個數字並排寫在手帳上：**噴泉 264 歲、水 2045 歲**。她抬起頭看著街頭藝人，也看著小Q：「我知道問題出在哪裡了。」',
                      en: '⚖️ 264 years! An-An writes the two numbers side by side: **fountain 264, water 2045.** She looks up at the performer, then at Little Q: “I see where the confusion is.”' },
