          emoji: '📊',
          diagram: 'bar-chart',
          story: { zh: '阿嬤在牆上貼了一張手畫的長條圖：「我每年都數一次。這裡有四座神廟遺址，我叫它們甲、乙、丙、丁。」圖上四根長條清清楚楚：甲 {85} 隻、乙 {60} 隻、丙 {120} 隻、丁 {85} 隻。小Q：「安安，先看圖回答——哪一座住的貓最多？有幾隻？」',
                   en: 'On the wall the old woman has pinned a hand-drawn bar chart: “I count them once a year. There are four temple ruins here; I call them A, B, C and D.” Four bars stand clear on the chart: A {85}, B {60}, C {120}, D {85}. Little Q: “An-An, read the chart first — which temple has the most cats, and how many?”' },
          clueNote: { zh: '長條圖：甲85／乙60／丙120／丁85，最多的是丙，120 隻', en: 'Bar chart: A 85 / B 60 / C 120 / D 85 — the most is C, with 120' },
