            reward: { zh: '📊 120 隻！阿嬤笑了：「丙那一座有屋簷，下雨淋不到，貓最愛。」她邊說邊倒飼料，一群貓從四面八方湧過來。圓圓沒有動，就坐在階梯最上面看著。',
                      en: '📊 120! The old woman smiles: “C still has a bit of roof — no rain gets in, so the cats love it.” She pours out the food and cats stream in from every direction. Yuan-Yuan does not move; she sits at the top of the steps and watches.' },
