          story: { zh: '小Q繼續問：「再看一次圖。最多的丙有 {120} 隻，最少的乙只有 {60} 隻。差多少？」阿嬤補了一句：「乙那一座最曬，夏天沒有貓要待。可是冬天就變成最熱門的了——貓跟著太陽搬家的。」',
                   en: 'Little Q continues: “Look again. C, the most, has {120}; B, the fewest, only {60}. What is the difference?” The old woman adds: “B gets full sun — no cat will stay there in summer. But in winter it becomes the most popular of all. Cats move house with the sun.”' },
          clueNote: { zh: '丙 120 − 乙 60 ＝ 相差 60 隻；貓會跟著太陽搬家（阿嬤的話）', en: 'C 120 − B 60 = a gap of 60; cats move house with the sun (the old woman’s words)' },
